-- Restore the shared core permission keys while preserving existing group grants.
INSERT INTO "permission" ("key", "label", "appName", "createdAt", "updatedAt")
SELECT 'core_' || substring("key" FROM 12), "label", 'core', "createdAt", CURRENT_TIMESTAMP
FROM "permission" WHERE "key" IN ('backoffice_user:list', 'backoffice_user:get', 'backoffice_user:create', 'backoffice_user:update', 'backoffice_user:delete', 'backoffice_user:set-role', 'backoffice_user:ban', 'backoffice_session:list', 'backoffice_session:revoke', 'backoffice_group:list', 'backoffice_group:view', 'backoffice_group:create', 'backoffice_group:edit', 'backoffice_group:delete', 'backoffice_group:assign_permissions', 'backoffice_group:remove_permission', 'backoffice_group:assign_users', 'backoffice_group:remove_user', 'backoffice_permission:list', 'backoffice_audit_log:list')
ON CONFLICT ("key") DO UPDATE SET "appName" = 'core', "updatedAt" = CURRENT_TIMESTAMP;

INSERT INTO "group_permission" ("groupId", "permission")
SELECT "groupId", 'core_' || substring("permission" FROM 12)
FROM "group_permission" WHERE "permission" IN ('backoffice_user:list', 'backoffice_user:get', 'backoffice_user:create', 'backoffice_user:update', 'backoffice_user:delete', 'backoffice_user:set-role', 'backoffice_user:ban', 'backoffice_session:list', 'backoffice_session:revoke', 'backoffice_group:list', 'backoffice_group:view', 'backoffice_group:create', 'backoffice_group:edit', 'backoffice_group:delete', 'backoffice_group:assign_permissions', 'backoffice_group:remove_permission', 'backoffice_group:assign_users', 'backoffice_group:remove_user', 'backoffice_permission:list', 'backoffice_audit_log:list')
ON CONFLICT ("groupId", "permission") DO NOTHING;

DELETE FROM "group_permission" WHERE "permission" IN ('backoffice_user:list', 'backoffice_user:get', 'backoffice_user:create', 'backoffice_user:update', 'backoffice_user:delete', 'backoffice_user:set-role', 'backoffice_user:ban', 'backoffice_session:list', 'backoffice_session:revoke', 'backoffice_group:list', 'backoffice_group:view', 'backoffice_group:create', 'backoffice_group:edit', 'backoffice_group:delete', 'backoffice_group:assign_permissions', 'backoffice_group:remove_permission', 'backoffice_group:assign_users', 'backoffice_group:remove_user', 'backoffice_permission:list', 'backoffice_audit_log:list');
DELETE FROM "permission" WHERE "key" IN ('backoffice_user:list', 'backoffice_user:get', 'backoffice_user:create', 'backoffice_user:update', 'backoffice_user:delete', 'backoffice_user:set-role', 'backoffice_user:ban', 'backoffice_session:list', 'backoffice_session:revoke', 'backoffice_group:list', 'backoffice_group:view', 'backoffice_group:create', 'backoffice_group:edit', 'backoffice_group:delete', 'backoffice_group:assign_permissions', 'backoffice_group:remove_permission', 'backoffice_group:assign_users', 'backoffice_group:remove_user', 'backoffice_permission:list', 'backoffice_audit_log:list');
